SELECT * FROM (
    SELECT R.*, ROWNUM AS RN FROM (
        SELECT N.NOTI_NO, N.PERSON_ID, N.NOTI_TYPE, N.TITLE, N.BODY, N.REF_TYPE, N.REF_ID, N.REF_EXTRA,
               CASE WHEN N.READ_YN = 'Y' THEN 1 ELSE 0 END AS IS_READ,
               TO_CHAR(N.CREATE_DATE, 'DD/MM/YYYY HH24:MI') AS CREATE_DATE_STR
          FROM MB_NOTIFICATION N
         WHERE N.PERSON_ID = #{recipientId, jdbcType=VARCHAR}
         ORDER BY N.CREATE_DATE DESC, N.NOTI_NO DESC
    ) R WHERE ROWNUM <= #{offset, jdbcType=NUMERIC} + #{limit, jdbcType=NUMERIC}
) WHERE RN > #{offset, jdbcType=NUMERIC}

SELECT COUNT(1) FROM MB_NOTIFICATION
 WHERE PERSON_ID = #{recipientId, jdbcType=VARCHAR}
   AND READ_YN = 'N'

mapper.update:
UPDATE MB_NOTIFICATION
   SET READ_YN = 'Y', READ_DATE = SYSDATE
 WHERE PERSON_ID = #{recipientId, jdbcType=VARCHAR}
   AND NOTI_NO = #{notiNo, jdbcType=NUMERIC}
   AND READ_YN = 'N'

UPDATE MB_DEVICE
   SET FCM_TOKEN = NULL, UPDATE_DATE = SYSDATE
 WHERE DEVICE_ID = #{deviceId, jdbcType=VARCHAR}
   AND FCM_TOKEN = #{fcmToken, jdbcType=VARCHAR}
